package cn.mop.api;

import cn.mop.domain.DomainException;
import cn.mop.domain.calendar.WorkingCalendarDraft;
import cn.mop.domain.time.IntervalSets.Interval;
import cn.mop.domain.time.WorkingTime;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Synthetic draft scenarios only, not any customer's actual hours, holidays or SLA commitments. */
class WorkingCalendarDraftTest {
    static Instant at(long minute){return Instant.EPOCH.plusSeconds(minute*60);}
    static Interval window(long from,long to){return new Interval(at(from),at(to));}
    WorkingCalendarDraft draft(List<Interval> windows,boolean complete){return new WorkingCalendarDraft("合成试算草稿",window(0,6000),windows,complete,null);}
    @Test void rawWindowsStayImmutableAndCalculationsUseTheirUnion(){var raw=new ArrayList<>(List.of(window(90,150),window(0,60),window(30,90)));var draft=draft(raw,true);raw.clear();assertEquals(3,draft.workingWindows().size());assertEquals(List.of(window(0,150)),draft.normalizedWindows());assertThrows(UnsupportedOperationException.class,()->draft.workingWindows().clear());assertThrows(UnsupportedOperationException.class,()->draft.normalizedWindows().clear());}
    @Test void aCalculatedScenarioNeverBecomesAnEffectiveDeadline(){var draft=draft(List.of(window(0,60)),true);var result=draft.preview("SYNTHETIC-CALENDAR",7,at(0),Duration.ofMinutes(30));assertEquals(at(30),result.scenarioDeadline());assertNull(result.effectiveDeadline());assertFalse(result.effective());assertFalse(draft.effective());assertEquals("UNVERIFIED",draft.customerConfirmation());assertEquals("UNPUBLISHED_DRAFT_SCENARIO",result.scope());assertEquals("Asia/Shanghai",draft.timezone());assertEquals("SYNTHETIC-CALENDAR",result.arithmetic().calendarId());assertEquals(7L,result.arithmetic().calendarVersion());}
    @Test void missingDurationOrStartNeverUsesNextDayOrCurrentTimeDefaults(){var draft=new WorkingCalendarDraft("次日尚待确认",window(0,6000),List.of(window(0,6000)),true,"不得把次日解释成24小时");var missing=draft.preview("SYNTHETIC",1,at(0),null);assertEquals(WorkingTime.Reason.DURATION_MISSING,missing.arithmetic().reason());assertNull(missing.scenarioDeadline());assertNull(missing.arithmetic().remaining());assertEquals(WorkingTime.Reason.START_MISSING,draft.preview("SYNTHETIC",1,null,Duration.ofMinutes(1)).arithmetic().reason());}
    @Test void incompleteCoverageAndExplicitEmptyCalendarStayDifferent(){var incomplete=draft(List.of(),false).preview("SYNTHETIC",1,at(0),Duration.ofMinutes(1));assertEquals(WorkingTime.Reason.COVERAGE_INCOMPLETE,incomplete.arithmetic().reason());var empty=draft(List.of(),true).preview("SYNTHETIC",1,at(0),Duration.ofMinutes(1));assertEquals(WorkingTime.Reason.INSUFFICIENT_WORKING_TIME,empty.arithmetic().reason());assertNull(empty.scenarioDeadline());}
    @Test void explicitZeroIsArithmeticOnlyAndNotAnImplicitMissingValue(){var result=draft(List.of(),true).preview("SYNTHETIC",1,at(10),Duration.ZERO);assertEquals(at(10),result.scenarioDeadline());assertNull(result.effectiveDeadline());assertEquals(WorkingTime.Reason.COVERAGE_INCOMPLETE,draft(List.of(),false).preview("SYNTHETIC",1,at(10),Duration.ZERO).arithmetic().reason());}
    @Test void crossingClosedGapsPreservesOriginalSnapshotAndRequiredTime(){var original=draft(List.of(window(0,60),window(1440,1500)),true);var result=original.preview("SYNTHETIC",2,at(30),Duration.ofMinutes(60));var changed=draft(List.of(window(0,60)),true);assertEquals(at(1470),result.scenarioDeadline());assertNull(changed.preview("SYNTHETIC",3,at(30),Duration.ofMinutes(60)).scenarioDeadline());assertEquals(2L,result.arithmetic().calendarVersion());assertEquals(Duration.ZERO,result.arithmetic().remaining());}
    @Test void missingDraftInputsCannotBeConvertedIntoEmptyKnownCoverage(){for(Boolean complete:new Boolean[]{null})assertEquals(400,assertThrows(DomainException.class,()->new WorkingCalendarDraft("合成",window(0,60),List.of(),complete,null)).status);assertThrows(DomainException.class,()->new WorkingCalendarDraft("合成",null,List.of(),false,null));assertThrows(DomainException.class,()->new WorkingCalendarDraft("合成",window(0,60),null,false,null));assertThrows(DomainException.class,()->new WorkingCalendarDraft("合成",window(0,60),Arrays.asList((Interval)null),false,null));}
    @Test void textBoundsCountUnicodeAndKeepExplicitRawNotes(){String note="  原始说明\n第二行\t ";var draft=new WorkingCalendarDraft("😀".repeat(100),window(0,60),List.of(),false,note);assertEquals(note,draft.note());for(String name:new String[]{null,"","\ufeff\u00a0","name\n","x\ud800","😀".repeat(101)})assertThrows(DomainException.class,()->new WorkingCalendarDraft(name,window(0,60),List.of(),false,null));for(String bad:new String[]{"","\ufeff","x\u0000","😀".repeat(2001)})assertThrows(DomainException.class,()->new WorkingCalendarDraft("合成",window(0,60),List.of(),false,bad));}
    @Test void millisecondsCoverageAndTechnicalWindowBoundAreExplicit(){assertThrows(DomainException.class,()->new WorkingCalendarDraft("合成",window(0,60),List.of(window(-1,1)),true,null));assertThrows(DomainException.class,()->new WorkingCalendarDraft("合成",window(0,60),List.of(new Interval(at(0).plusNanos(1),at(1))),true,null));assertDoesNotThrow(()->draft(Collections.nCopies(1000,window(0,1)),true));assertThrows(DomainException.class,()->draft(Collections.nCopies(1001,window(0,1)),true));}
    @Test void previewRequiresExplicitIdentityVersionAndValidTimeInputs(){var draft=draft(List.of(window(0,60)),true);assertThrows(DomainException.class,()->draft.preview(null,1,at(0),Duration.ZERO));assertThrows(DomainException.class,()->draft.preview(" ",1,at(0),Duration.ZERO));assertThrows(DomainException.class,()->draft.preview("SYNTHETIC",0,at(0),Duration.ZERO));assertThrows(DomainException.class,()->draft.preview("SYNTHETIC",1,at(0),Duration.ofNanos(-1)));assertThrows(DomainException.class,()->draft.preview("SYNTHETIC",1,at(0).plusNanos(1),Duration.ZERO));assertEquals(WorkingTime.Reason.START_OUTSIDE_COVERAGE,draft.preview("SYNTHETIC",1,at(-1),Duration.ZERO).arithmetic().reason());}
}
